  ],
  kuendigung: [
    { id: "befristet", label: "Bis Baubeginn", sub: "Rücktritt befristet" },
    { id: "unbefristet", label: "Offen", sub: "Rücktritt ohne Frist" },
    { id: "jederzeit", label: "Jederzeit", sub: "auch im Betrieb" },
  ],
